RTriggerCyl01(CLK := g_bBlankingCyl0DownOpenM);
RTriggerCyl02(CLK := g_bBlankingCyl0DownCloseM);

RTriggerCyl11(CLK := g_bBlankingCyl1DownOpenM);
RTriggerCyl12(CLK := g_bBlankingCyl1DownCloseM);

RTriggerCyl21(CLK := g_bBlankingCyl2DownOpenM);
RTriggerCyl22(CLK := g_bBlankingCyl2DownCloseM);

RTriggerCyl31(CLK := g_bBlankingCyl3DownOpenM);
RTriggerCyl32(CLK := g_bBlankingCyl3DownCloseM);

RTriggerCyl41(CLK := g_bBlankingCyl4DownOpenM);
RTriggerCyl42(CLK := g_bBlankingCyl4DownCloseM);

(*第零组气缸*)
IF RTriggerCyl01.Q THEN
  nCyl0DownState := 1;
  g_boBlankingCyl0DownDone := FALSE;
  g_bBlankingCyl0DownOpenM := FALSE;
  g_bBlanking1DelayFlag := TRUE;
END_IF;

IF RTriggerCyl02.Q THEN
  g_boBlankingCyl0DownDone := FALSE;
  g_bBlankingCyl0DownCloseM := FALSE;
  nCyl0DownState := 0;
  g_bBlanking1DelayFlag := TRUE;
END_IF;

CASE nCyl0DownState OF
  0:
    nCyl0DownState := 0;
    nPreCyl0DownState := 0;
  1:
    IF LREAL_TO_INT(g_fBlankingCyl0MoveTypeM) = 0 THEN
      nCyl0DownState := 2; (*下降*)
    ELSIF LREAL_TO_INT(g_fBlankingCyl0MoveTypeM) = 1 AND (NOT g_bClaw3CylForbid) THEN
      nCyl0DownState := 3;(*上升*)
    END_IF;
  2:
    IF g_dBlankingCylinder1WaitBoardInputSignalM = 0.0 THEN
      nCyl0DownState := 10;
    ELSE
      M.ENABLE[206] := 0;
      nCyl0DownState := 15;
      g_bExecuteFinishedM206 := FALSE;
	  g_bFinishedM206_0 := FALSE;
    END_IF;
  10:
    nPreCyl0DownState := nCyl0DownState;
    IF g_dBlankingCylinder1WaitSignalM = 0.0 OR g_dBlankingCylinder1WaitSignalM = 1.0 THEN
         nCyl0DownState := 20;
      ELSIF g_dBlankingCylinder1WaitSignalM = 2.0 THEN
        M.ENABLE[206] := 0;
        g_bExecuteFinishedM206 := FALSE;
		g_bFinishedM206_0 := FALSE;
        IF NOT g_bBlankingStateUp2 THEN
          nCyl0DownState := 20;
        END_IF;
      ELSIF g_dBlankingCylinder1WaitSignalM = 3.0 THEN
        M.ENABLE[206] := 0;
        g_bExecuteFinishedM206 := FALSE;
		g_bFinishedM206_0 := FALSE;
        IF NOT g_bBlankingStateUp3 THEN
          nCyl0DownState := 20;
        END_IF;
      ELSIF g_dBlankingCylinder1WaitSignalM = 4.0 THEN
        M.ENABLE[206] := 0;
        g_bExecuteFinishedM206 := FALSE;
		g_bFinishedM206_0 := FALSE;
        IF NOT g_bBlankingStateUp4 THEN
          nCyl0DownState := 20;
        END_IF;
      ELSIF g_dBlankingCylinder1WaitSignalM = 5.0 THEN
        M.ENABLE[206] := 0;
        g_bExecuteFinishedM206 := FALSE;
		g_bFinishedM206_0 := FALSE;
        IF NOT g_bBlankingStateUp5 THEN
          nCyl0DownState := 20;
        END_IF;
      END_IF; 
    IF g_bPlcPauseBuffer THEN
      nCyl0DownState := 12;
    END_IF;
  15:
    nPreCyl0DownState := nCyl0DownState;
    nBlankingCyl1UpIndex :=LREAL_TO_INT(g_dBlankingCylinder1WaitSignalM) - 1;
    IF g_dBlankingCylinder1WaitBoardInputSignalM = 1.0 THEN
      IF BoardInPutArray.BoolArr[nBlankingCyl1UpIndex] THEN
        nCyl0DownState := 20;
      END_IF;
    ELSIF g_dBlankingCylinder1WaitBoardInputSignalM = 2.0 THEN
      IF BoardInPutArray.BoolArr[nBlankingCyl1UpIndex + 24] THEN
        nCyl0DownState := 20;
      END_IF;
    ELSIF g_dBlankingCylinder1WaitBoardInputSignalM = 3.0 THEN
      IF BoardInPutArray.BoolArr[nBlankingCyl1UpIndex + 48] THEN
        nCyl0DownState := 20;
      END_IF;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nCyl0DownState := 12;
    END_IF;
  20:
    nPreCyl0DownState := nCyl0DownState;
    g_boBlankingCyl01Up := FALSE;
    g_boBlankingCyl01Down := TRUE;
    IF NOT g_bBlankingStateUp1 THEN
        g_boBlankingCyl0DownDone := TRUE;
        nCyl0DownState := 0;
        M.ENABLE[206] := 0;
        g_bExecuteFinishedM206 := FALSE;
		g_bFinishedM206_0 := FALSE;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nCyl0DownState := 12;
    END_IF;
  3:
    IF g_dBlankingCylinder1WaitBoardInputSignalM = 0.0 THEN
      nCyl0DownState := 30;
    ELSE
      M.ENABLE[206] := 0;
      nCyl0DownState := 35;
    END_IF;
  30:
    nPreCyl0DownState := nCyl0DownState;
    IF g_dBlankingCylinder1WaitSignalM = 0.0 OR g_dBlankingCylinder1WaitSignalM = 1.0 THEN
         nCyl0DownState := 40;
      ELSIF g_dBlankingCylinder1WaitSignalM = 2.0 THEN
        M.ENABLE[206] := 0;
        g_bExecuteFinishedM206 := FALSE;
		g_bFinishedM206_0 := FALSE;
        IF  g_bBlankingStateUp2 THEN
          nCyl0DownState := 40;
        END_IF;
      ELSIF g_dBlankingCylinder1WaitSignalM = 3.0 THEN
        M.ENABLE[206] := 0;
        g_bExecuteFinishedM206 := FALSE;
		g_bFinishedM206_0 := FALSE;
        IF  g_bBlankingStateUp3 THEN
          nCyl0DownState := 40;
        END_IF;
      ELSIF g_dBlankingCylinder1WaitSignalM = 4.0 THEN
        M.ENABLE[206] := 0;
        g_bExecuteFinishedM206 := FALSE;
		g_bFinishedM206_0 := FALSE;
        IF  g_bBlankingStateUp4 THEN
          nCyl0DownState := 40;
        END_IF;
      ELSIF g_dBlankingCylinder1WaitSignalM = 5.0 THEN
        M.ENABLE[206] := 0;
        g_bExecuteFinishedM206 := FALSE;
		g_bFinishedM206_0 := FALSE;
        IF  g_bBlankingStateUp5 THEN
          nCyl0DownState := 40;
        END_IF;
      END_IF; 
      IF g_bPlcPauseBuffer THEN
      nCyl0DownState := 12;
    END_IF;
  35:
    nPreCyl0DownState := nCyl0DownState;
    nBlankingCyl1DownIndex :=LREAL_TO_INT(g_dBlankingCylinder1WaitSignalM) - 1;
    IF g_dBlankingCylinder1WaitBoardInputSignalM = 1.0 THEN
      IF BoardInPutArray.BoolArr[nBlankingCyl1DownIndex] THEN
        nCyl0DownState := 40;
      END_IF;
    ELSIF g_dBlankingCylinder1WaitBoardInputSignalM = 2.0 THEN
      IF BoardInPutArray.BoolArr[nBlankingCyl1DownIndex + 24] THEN
        nCyl0DownState := 40;
      END_IF;
    ELSIF g_dBlankingCylinder1WaitBoardInputSignalM = 3.0 THEN
      IF BoardInPutArray.BoolArr[nBlankingCyl1DownIndex + 48] THEN
        nCyl0DownState := 40;
      END_IF;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nCyl0DownState := 12;
    END_IF;
  40:
    nPreCyl0DownState := nCyl0DownState;
    g_boBlankingCyl01Up := TRUE;
    g_boBlankingCyl01Down := FALSE;
    IF g_bBlankingStateUp1 THEN
        g_boBlankingCyl0DownDone := TRUE;
        nCyl0DownState := 0;
        M.ENABLE[206] := 0;
        g_bExecuteFinishedM206 := FALSE;
		g_bFinishedM206_0 := FALSE;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nCyl0DownState := 12;
    END_IF;
  12:
    IF g_bPlcStartBuffer OR g_bPlcStartM THEN
      nCyl0DownState := nPreCyl0DownState;
    END_IF;

END_CASE;

